function columnSums(matrix) {
  if (!matrix.length) return [];
  const cols = matrix[0].length;
  const sums = Array(cols).fill(0);
  for (let i = 0; i < matrix.length; i++) {
    for (let j = 0; j < cols; j++) {
      sums[j] += matrix[i][j];
    }
  }
  return sums;
}
